			if !errors.Is(commitErr, errExportTargetNotCommit) {
				if freshLookup != nil {
					// Defensive: resolveCheckpointFromCommitRef documents a
					// nil lookup on error, but a leak here would be silent.
					_ = freshLookup.Close()
				}
				return id.CheckpointID(""), lookup, commitErr
			}
		}
