const specs = [
  ["cmd/entire/cli/review/intentlens/audit.go", true],
  ["cmd/entire/cli/review/intentlens/audit.schema.json", false],
  ["cmd/entire/cli/review/intentlens/evaluator.go", false],
  ["cmd/entire/cli/review/intentlens/prompts.go", false],
];
for (const [file, trimDemo] of specs) {
  const r = await tools.exec_command({cmd:`git show audit-ui:${file}`,workdir:"C:\\Users\\gshek\\cli-btw",yield_time_ms:10000,max_output_tokens:30000});
  if (r.exit_code !== 0) { text(r.output); exit(); }
  let content = r.output.replace(/\r\n/g, "\n");
  if (trimDemo) {
    content = content
      .replace(/\n\t_ "embed"/, "")
      .replace(/\n\t\/\/go:embed testdata\/expected-audit\.json\n\tdemoAudit \[\]byte\n/, "\n")
      .replace(/\nfunc DemoAuditJSON\(\) \[\]byte \{ return bytes\.Clone\(demoAudit\) \}\n/, "\n");
  }
  const patch = `*** Begin Patch\n*** Add File: ${file}\n` + content.split("\n").map(line => `+${line}`).join("\n") + "\n*** End Patch";
  await tools.apply_patch(patch);
}
